/* ---- util.js ---- */
/* VITAWAW · js/util.js
   Small helpers used everywhere: esc() (escape HTML), normAr() (Arabic-insensitive search), $(id), fmt(), R() (source badges).
   Files are plain scripts loaded in order by index.html (shared global scope, no build step). */
/** Escape text before putting it inside HTML (always use this for data from the database). */
/** 1.14.0: «وLatin» (Arabic «and» glued to a Latin word) is shown reversed in right-to-left text; a space keeps it readable */
const bidiFix=s=>String(s??'').replace(/([A-Za-z0-9)])\s+و(?=[A-Za-z0-9])/g,'$1، ').replace(/([\u0600-\u06FF])?و(?=[A-Za-z0-9])/g,(m,a)=>a?m:'و ');
/* between two English names the Arabic «و» becomes «،» (in these fonts a lone «و» beside Latin letters looks like «g») */
const esc=x=>bidiFix(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normAr=x=>String(x||'').toLowerCase().replace(/[أإآا]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/[\u064B-\u0652]/g,'').replace(/\s+/g,' ').trim();
const $=id=>document.getElementById(id);
/** HTML → plain text for copying/sharing: removes tags and turns codes like &#39; back into characters */
const plain=x=>{const t=document.createElement('textarea');t.innerHTML=String(x||'').replace(/<[^>]+>/g,'');return t.value};
const EYE='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg>';
const EYEOFF='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M3 3l18 18M10.6 5.1A10.4 10.4 0 0 1 12 5c6.4 0 10 7 10 7a17 17 0 0 1-3.2 4M6.6 6.6C3.9 8.3 2 12 2 12s3.6 7 10 7a9.7 9.7 0 0 0 5.4-1.6"/><path d="M9.9 9.9a3 3 0 0 0 4.2 4.2"/></svg>';
const TRASH='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13"/></svg>';
const PEN='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M4 20h4L19 9l-4-4L4 16z"/></svg>';
const PLUS='<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 8v8M8 12h8"/></svg>';
/** Drag to reorder: press the ⋮⋮ handle (.drag) of an item and move it, or use the arrow keys on the handle.
   onDone(ids) gets the new order of the items' data-sid. Works for lists and wrapped grids. */
function sortable(box,sel,onDone,hsel='.drag'){
  if(!box||box._sortable)return;box._sortable=true;
  const ids=()=>[...box.querySelectorAll(sel)].map(x=>x.dataset.sid);
  box.addEventListener('pointerdown',e=>{
    const h=e.target.closest(hsel);if(!h||!box.contains(h))return;const item=h.closest(sel);if(!item||!box.contains(item))return;
    e.preventDefault();const start=ids().join();item.classList.add('dragging');box.setPointerCapture(e.pointerId);
    const move=ev=>{
      if(ev.clientY<70)scrollBy(0,-12);else if(ev.clientY>innerHeight-90)scrollBy(0,12);
      const over=document.elementFromPoint(ev.clientX,ev.clientY);const t=over&&over.closest(sel);
      if(!t||t===item||!box.contains(t)||t.parentNode!==item.parentNode)return; // 1.14.1: only inside the same group
      const all=[...box.querySelectorAll(sel)];if(all.indexOf(item)<all.indexOf(t))t.after(item);else t.before(item);
    };
    const up=()=>{box.removeEventListener('pointermove',move);box.removeEventListener('pointerup',up);box.removeEventListener('pointercancel',up);
      item.classList.remove('dragging');const now=ids();if(now.join()!==start)onDone(now,item)};
    box.addEventListener('pointermove',move);box.addEventListener('pointerup',up);box.addEventListener('pointercancel',up);
  });
  box.addEventListener('keydown',e=>{
    const h=e.target.closest(hsel);if(!h||!box.contains(h))return;const d={ArrowUp:-1,ArrowLeft:-1,ArrowDown:1,ArrowRight:1}[e.key];if(!d)return;
    e.preventDefault();const it=h.closest(sel),now=ids(),i=now.indexOf(it.dataset.sid),j=i+(document.dir==='rtl'&&/Left|Right/.test(e.key)?-d:d);
    if(j<0||j>=now.length)return;const o=box.querySelector(`${sel}[data-sid="${CSS.escape(now[j])}"]`);if(!o||o.parentNode!==it.parentNode)return;[now[i],now[j]]=[now[j],now[i]];onDone(now,it);
    setTimeout(()=>{const n=box.querySelector(`${sel}[data-sid="${CSS.escape(now[j])}"] .drag`);if(n)n.focus()},0);
  });
}
const DRAG=t=>`<button type="button" class="drag" aria-label="${esc(t)}" title="${esc(t)}"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="9" cy="6" r="1.6"/><circle cx="15" cy="6" r="1.6"/><circle cx="9" cy="12" r="1.6"/><circle cx="15" cy="12" r="1.6"/><circle cx="9" cy="18" r="1.6"/><circle cx="15" cy="18" r="1.6"/></svg></button>`;
const fmt=n=>Number(n).toLocaleString('en-US',{maximumFractionDigits:1});
/** source numbers [n] */
const R=a=>(a||[]).filter(n=>REFS[n]).map(n=>`<a class="ref" href="#" data-ref="${n}" title="${esc(REFS[n][0])}">${n}</a>`).join('');
let K='d',LAST=null;
/** show the form fields of the chosen calculator: data-for = only for these, data-not = all except these */
function showFor(){document.querySelectorAll('[data-for]').forEach(el=>{el.hidden=!el.dataset.for.split(' ').includes(K)});document.querySelectorAll('[data-not]').forEach(el=>{el.hidden=el.dataset.not.split(' ').includes(K)})}

/* ---- validation.js ---- */
/* VITAWAW · js/validation.js
   Input checks for the calculator fields (allowed ranges, error messages, the 'missing data' state).
   Files are plain scripts loaded in order by index.html (shared global scope, no build step). */
/* ===================== input validation ===================== */
const RANGE={age:[0,110],wt:[2,250],ht:[40,230],b12v:[20,3000],cadiet:[0,4000],ab12:[5,300],hb:[3,25],fer:[1,5000]};
function rangeOf(id){
  if(id==='dlab')return $('dunit').value==='nmol'?[2,1000]:[1,400];
  if(id==='mgv')return $('mgu').value==='mmol'?[0.1,3]:[0.2,6];
  if(id==='b12v')return $('b12u').value==='pmol'?[15,2200]:[20,3000];
  if(id==='mon')return K==='vac'?[0,59]:[0,24];
  return RANGE[id];
}
function errEl(id){let e=$('e-'+id);if(!e){e=document.createElement('p');e.className='err';e.id='e-'+id;e.hidden=true;const host=$(id).closest('.unit')||$(id);host.after(e)}return e}
function val(id){
  const el=$(id),raw=el.value.trim(),e=errEl(id);
  if(raw===''){el.classList.remove('bad');e.hidden=true;return {s:'empty'}}
  const v=parseFloat(raw),rg=rangeOf(id);
  if(isNaN(v)||(rg&&(v<rg[0]||v>rg[1]))){el.classList.add('bad');e.hidden=false;e.textContent=`${T('e_range')} ${fmt(rg[0])} – ${fmt(rg[1])}`;return {s:'bad'}}
  el.classList.remove('bad');e.hidden=true;return {s:'ok',v};
}
/* returns values or null after rendering the empty/invalid state */
function req(list,opt=[]){
  const out={},missing=[],bad=[];
  [...list,...opt].forEach(id=>{const r=val(id);if(r.s==='ok')out[id]=r.v;else{out[id]=null;if(r.s==='bad')bad.push(id);else if(list.includes(id))missing.push(id)}});
  if(bad.length||missing.length){emptyState(missing,bad);return null}
  return out;
}
const FIELDNAME={age:'age',wt:'wt',ht:'ht',dlab:'dlab',b12v:'b12v',mgv:'mgv',cadiet:'cadiet',ab12:'ab12',hb:'hb',fer:'fer',mon:'mon'};
function emptyState(missing,bad){
  LAST=null;
  // nothing typed yet: no result box at all (it appears as soon as the visitor enters data or asks for an example)
  $('calc').classList.toggle('nores',![...document.querySelectorAll('#s-data input[type="number"]')].some(i=>i.value.trim()));
  const items=[...missing.map(id=>`<li>${T(FIELDNAME[id])}</li>`),...bad.map(id=>`<li style="color:var(--bad)">${T(FIELDNAME[id])}: ${T('e_range').split(':')[0]}</li>`)].join('');
  $('res').dataset.h='';$('res').innerHTML=`<div class="empty"><b>${T('e_empty_t')}</b>${items?`<div>${T('e_need')}<ul>${items}</ul></div>`:''}<button class="btn pri" type="button" data-ex>${T('ex')}</button></div>`;
  $('rtx').textContent=T('e_empty_t');$('rdot').style.background='var(--mute)';
}

