/* ===================== Calcium ===================== */
function fCa(){
  const x=req(['age'],['cadiet']);if(!x)return;
  const age=x.age,sx=$('sex').value,known=x.cadiet!=null,diet=x.cadiet||0,MG=L(' ملغ',' mg');
  let rda;
  if(sx==='p'||sx==='l')rda=teen(age)?1300:1000;
  else rda=age<1?'200 – 260':age<=3?700:age<=8?1000:age<=18?1300:age<=50?1000:age<=70?(sx==='m'?1000:1200):1200;
  const rdaT=typeof rda==='number'?fmt(rda):rda;
  const ul=age<1?'1,000 – 1,500':age<=8?'2,500':age<=18?'3,000':age<=50?'2,500':'2,000';
  const kv=[[RDAL(age),rdaT+MG],[L('الحد الأعلى الآمن (UL)','Tolerable Upper Intake Level (UL)'),ul+L(' ملغ / يوم',' mg / day')]];
  let r;
  if(age<1){r={badge:L('الرضيع','Infant'),tone:'info',title:L(`${rdaT} ملغ يومياً من الحليب والغذاء`,`${rdaT} mg daily from milk and food`),sub:L('لا يحتاج الرضيع مكمل كالسيوم؛ حليب الأم أو الحليب الصناعي يكفيه، ثم الأطعمة المكمّلة بعد 6 أشهر. أي مكمل بقرار طبيب الأطفال فقط','Infants do not need a calcium supplement: breast milk or formula is enough, then complementary foods from 6 months. Any supplement only as the pediatrician decides'),refs:[18],
    pt:L('الرضيع لا يحتاج حبوب أو شراب كالسيوم؛ الحليب يكفيه.','Your baby does not need calcium tablets or syrup; milk is enough.')};
    r.notes=[{t:L('القيم للرضّع مدخول كافٍ (AI): 200 ملغ حتى 6 أشهر و260 ملغ من 7 إلى 12 شهراً.','Infant values are adequate intakes (AI): 200 mg to 6 months and 260 mg from 7 to 12 months.'),r:[18],i:1}];r.kv=kv;render(r);return}
  if(!known){r={badge:L('الاحتياج اليومي','Daily requirement'),tone:'info',title:L(`${rdaT} ملغ كالسيوم يومياً من الغذاء والمكملات معاً`,`${rdaT} mg calcium daily from food and supplements combined`),sub:L('أدخل الكالسيوم من الطعام لحساب كمية المكمل اللازمة بالضبط','Enter dietary calcium to calculate the exact supplement needed'),refs:[18],
    pt:L(`تحتاج ${rdaT} ملغ كالسيوم يومياً من الطعام والمكملات معاً.`,`You need ${rdaT} mg of calcium a day from food and supplements together.`)}}
  else{
    const gap=Math.max(0,(typeof rda==='number'?rda:260)-diet),doses=Math.ceil(gap/500);kv.push([L('من الغذاء','From food'),fmt(diet)+MG]);
    if(gap===0)r={badge:L('المدخول الغذائي كافٍ','Dietary intake meets the requirement'),tone:'ok',title:L('لا حاجة لمكمل كالسيوم','No calcium supplement needed'),sub:L('المدخول الغذائي المدخل يساوي الاحتياج أو يزيد عليه','The entered dietary intake meets or exceeds the need'),refs:[18],pt:L('طعامك يكفي، ولا تحتاج حبوب كالسيوم.','Your diet is enough; you do not need calcium tablets.')};
    else{r={badge:L('نقص في المدخول','Intake below requirement'),tone:'warn',title:L(`مكمل ${fmt(gap)} ملغ كالسيوم عنصري يومياً`,`Supplement ${fmt(gap)} mg elemental calcium daily`),sub:doses>1?L(`مقسّمة على ${doses===2?'جرعتين':doses+' جرعات'}، لا تزيد الجرعة الواحدة على 500 ملغ`,`Split into ${doses} doses, no more than 500 mg each`):L('جرعة واحدة لا تزيد على 500 ملغ','One dose of no more than 500 mg'),refs:[18],
      pt:doses>1?L(`تحتاج ${fmt(gap)} ملغ كالسيوم إضافية يومياً، مقسّمة على ${doses===2?'مرتين':doses+' مرات'} (لا تزيد كل مرة على 500 ملغ).`,`You need ${fmt(gap)} mg more calcium a day, split into ${doses} doses (no more than 500 mg each).`):L(`تحتاج ${fmt(gap)} ملغ كالسيوم إضافية يومياً في جرعة واحدة.`,`You need ${fmt(gap)} mg more calcium a day in one dose.`),
      opts:[{h:'Calcium carbonate',b:L('مع الطعام','With food'),d:L('يحتاج حمض المعدة للامتصاص','Needs stomach acid to be absorbed'),r:[18]},{h:'Calcium citrate',b:L('مع الطعام أو بدونه','With or without food'),d:L('أنسب لمن يتناول أدوية تقلل حمض المعدة','Better for people on acid-reducing medicines'),r:[18]}]};
      r.tool='pills';PILL={k:'ca',dose:Math.min(500,Math.ceil(gap/doses))};r.sch=doses>1?['ca','ca2']:['ca'];if(age>=1)r.ul=[['ca',diet+gap]];r.cal={title:L('الكالسيوم','Calcium')+(doses>1?L(` (${doses} مرات مع الوجبات)`,` (${doses} times with meals)`):''),freq:'DAILY'};}
  }
  r.notes=[{t:L('الإجمالي (غذاء + مكمل) يجب ألا يتجاوز الحد الأعلى.','Total intake (food + supplement) should stay under the upper limit.'),r:[18]}];
  if(CKD())r.notes.unshift({t:L('في القصور الكلوي المتقدم يحدد طبيب الكلى الكالسيوم والفوسفات؛ تُتجنّب الجرعات العالية من الكالسيوم لخطر ارتفاعه وترسّبه.','In advanced kidney disease the nephrologist manages calcium and phosphate; high calcium doses are avoided because of hypercalcemia and calcification risk.'),r:[61],u:1});
  if(sx==='p')r.notes.push({t:L('توصي منظمة الصحة العالمية بـ 1,500 – 2,000 ملغ يومياً للحوامل ذوات المدخول المنخفض لتقليل خطر مقدمات الارتعاج (تسمم الحمل).','WHO recommends 1,500–2,000 mg daily for pregnant women with low intake to reduce preeclampsia risk.'),r:[18],i:1});
  r.kv=kv;render(r);
}

