/* ===================== Vitamin C ===================== */
function fC(){
  const x=req(['age']);if(!x)return;
  const age=x.age,sx=$('sex').value,g=$('czg').value,smk=$('smk').checked,MG=L(' ملغ',' mg');
  let rda=sx==='p'?(teen(age)?80:85):sx==='l'?(teen(age)?115:120):age<1?'40 – 50':age<=3?15:age<=8?25:age<=13?45:age<=18?(sx==='m'?75:65):(sx==='m'?90:75);
  if(smk&&age>=14&&typeof rda==='number')rda+=35;
  const ul=age<1?L('غير محدد','Not established'):(age<=3?'400':age<=8?'650':age<=13?'1,200':age<=18?'1,800':'2,000')+MG+L(' / يوم',' / day');
  const kv=[[RDAL(age),rda+MG+(smk?L(' (شامل إضافة المدخن)',' (includes smoker addition)'):'')],[L('الحد الأعلى الآمن (UL)','Tolerable Upper Intake Level (UL)'),ul]];
  let r;
  if(g==='rda')r={badge:L('الاحتياج اليومي','Daily requirement'),tone:'info',title:L(`${rda} ملغ فيتامين C يومياً`,`${rda} mg vitamin C daily`),sub:L('من الفواكه والخضار أو المكملات','From fruit and vegetables or supplements'),refs:[23],pt:L(`تحتاج ${rda} ملغ فيتامين C يومياً، ويوفرها غالباً تناول الفواكه والخضار.`,`You need ${rda} mg of vitamin C a day, which fruit and vegetables usually provide.`)};
  else r={badge:L('نزلات البرد','Common cold'),tone:'info',title:L('لا توجد جرعة علاجية مثبتة بعد بدء البرد','No proven treatment dose once a cold starts'),sub:L('تجارب أخذ فيتامين C بعد ظهور الأعراض لم تُظهر أثراً ثابتاً','Trials of vitamin C started after symptoms showed no consistent effect'),refs:[24],
    pt:L('أخذ فيتامين C بعد بدء البرد لم يثبت أنه يفيد. أخذه بانتظام قد يقصّر البرد قليلاً.','Taking vitamin C after a cold starts has not been shown to help. Taking it regularly may shorten colds a little.'),
    opts:[{h:L('الاستعمال المنتظم (200 ملغ يومياً فأكثر)','Regular use (200 mg daily or more)'),b:L('لا يقلل عدد مرات الإصابة لدى عامة الناس','Does not reduce how often people catch colds'),d:L('لكنه قصّر مدة البرد قليلاً بشكل ثابت في التجارب','But it consistently shortened colds slightly in trials'),r:[24]}]};
  if(g==='rda'&&typeof rda==='number'&&age>=1)r.ul=[['c',rda]];
  const ckdC=CKD()?[{t:L('في القصور الكلوي تُتجنّب جرعات فيتامين C فوق الاحتياج إلا بإشراف الطبيب، لأن الجرعات العالية ترفع الأوكسالات في البول.','In kidney disease avoid vitamin C above the daily need unless a doctor supervises, because high doses raise urinary oxalate.'),r:[23],u:1}]:[];
  r.kv=kv;r.notes=[...ckdC,{t:L('الجرعات العالية قد تسبب اضطراباً هضمياً، ويرتبط الاستعمال العالي بخطر حصى الكلى لدى بعض الأشخاص.','High doses can upset the stomach, and high intake is linked to kidney stone risk in some people.'),r:[23]}];render(r);
}

/* ===================== Zinc ===================== */
function fZn(){
  const x=req(['age']);if(!x)return;
  const age=x.age,sx=$('sex').value,g=$('czg').value,MG=L(' ملغ',' mg');
  const rda=sx==='p'?(teen(age)?12:11):sx==='l'?(teen(age)?13:12):age<1?'2 – 3':age<=3?3:age<=8?5:age<=13?8:age<=18?(sx==='m'?11:9):(sx==='m'?11:8);
  const ul=(age<1?'4 – 5':age<=3?'7':age<=8?'12':age<=13?'23':age<=18?'34':'40')+MG+L(' / يوم',' / day');
  const kv=[[RDAL(age),rda+L(' ملغ زنك عنصري',' mg elemental zinc')],[L('الحد الأعلى الآمن (UL)','Tolerable Upper Intake Level (UL)'),ul]];
  let r;
  // 1.16.0: acute diarrhoea in children under 5 (WHO/UNICEF 2004): 10 mg under 6 months, 20 mg from 6 months, for 10–14 days with ORS
  if(g==='dia'){
    const cur=age<1?L('أقل من 6 أشهر: 10 ملغ يومياً · من 6 أشهر: 20 ملغ يومياً','Under 6 months: 10 mg daily · from 6 months: 20 mg daily'):L('20 ملغ زنك عنصري يومياً','20 mg elemental zinc daily');
    r=age>=5?{badge:L('إسهال الأطفال','Childhood diarrhoea'),tone:'warn',title:L('التوصية لمن هم دون 5 سنوات','The recommendation is for children under 5'),sub:L('توصية WHO/UNICEF للزنك مع الإسهال الحاد تخص الأطفال دون 5 سنوات','The WHO/UNICEF zinc recommendation for acute diarrhoea covers children under 5'),refs:[85]}
      :{badge:L('إسهال الأطفال الحاد','Acute childhood diarrhoea'),tone:'ok',title:cur,sub:L('لمدة 10 – 14 يوماً، مع محلول الإرواء الفموي (ORS)','For 10–14 days, together with oral rehydration salts (ORS)'),refs:[85],
        plan:[{h:L('الجرعة','Dose'),d:cur+R([85])},{h:L('المدة','Duration'),d:L('10 – 14 يوماً حتى لو توقف الإسهال قبلها','10–14 days, even if the diarrhoea stops sooner')+R([85])},{h:L('مع','With'),d:L('محلول الإرواء الفموي منخفض التركيز، واستمرار الرضاعة والتغذية','Low-osmolarity ORS, and continued breastfeeding and feeding')+R([85])}]};
    r.kv=kv;r.notes=[{t:L('علامات الجفاف الشديد أو الدم في البراز أو استمرار الإسهال أكثر من 14 يوماً تحتاج طبيباً.','Signs of severe dehydration, blood in the stool or diarrhoea lasting over 14 days need a doctor.'),i:1}];
    return render(r);
  }
  if(g==='rda')r={badge:L('الاحتياج اليومي','Daily requirement'),tone:'info',title:L(`${rda} ملغ زنك يومياً`,`${rda} mg zinc daily`),sub:L('من الغذاء أو المكملات','From food or supplements'),refs:[25],pt:L(`تحتاج ${rda} ملغ زنك يومياً من الطعام أو المكملات.`,`You need ${rda} mg of zinc a day from food or supplements.`)};
  else r={badge:L('نزلات البرد','Common cold'),tone:'warn',title:L('فائدة محتملة لكنها غير مؤكدة','Possible benefit, not proven'),sub:L('مراجعة Cochrane 2024: قد يقصّر الزنك مدة البرد بنحو يومين، والثقة في الأدلة منخفضة، ولم يثبت أنه يمنع الإصابة','Cochrane 2024: zinc may shorten colds by about 2 days, with low-certainty evidence; it has not been shown to prevent colds'),refs:[26],
    pt:L('الزنك قد يقصّر البرد يومين تقريباً، لكن الدليل ضعيف. إن استخدمته فلأيام قليلة فقط، فقد يسبب غثياناً وتغيراً في الطعم.','Zinc may shorten a cold by about 2 days, but the evidence is weak. If you use it, only for a few days; it can cause nausea and a changed taste.'),
    opts:[{h:L('إن استُخدم','If used'),b:L('دورة قصيرة فقط','Short course only'),d:L('الجرعات المدروسة في أقراص الاستحلاب تتجاوز غالباً الحد الأعلى اليومي، ومن آثارها الغثيان وتغير الطعم','Doses studied in lozenges often exceed the daily upper limit; side effects include nausea and altered taste'),r:[26,25]}]};
  if(g==='rda'&&typeof rda==='number'&&age>=1){r.ul=[['zn',rda]];r.sch=['zn']}
  r.kv=kv;r.notes=[{t:L('الاستعمال الطويل فوق الحد الأعلى قد يسبب نقص النحاس. والحديد بجرعة 25 ملغ فأكثر يقلل امتصاص الزنك إذا أُخذا معاً.','Long-term use above the upper limit can cause copper deficiency. Iron at 25 mg or more lowers zinc absorption when taken together.'),r:[25]}];render(r);
}

/* ===================== Infant (0–24 months): vitamin K, vitamin D, iron ===================== */
function fInf(){
  const x=req(['mon'],['wt']);if(!x)return;
  const m=x.mon,w=x.wt,feed=$('feed').value,pre=$('pre').checked,bf=feed!=='ff',day=L(' / يوم',' / day');
  const kv=[[L('العمر','Age'),fmt(m)+L(' شهر',' months')]];
  const plan=[],notes=[];
  // vitamin K: one IM dose at birth (AAP 2022)
  if(m<1)plan.push({h:L('فيتامين K عند الولادة','Vitamin K at birth'),d:L('1 ملغ عضلياً جرعة واحدة (0.3 – 0.5 ملغ/كغم لمن وزنه أقل من 1,500 غ)','1 mg IM, single dose (0.3–0.5 mg/kg if under 1,500 g)')});
  else notes.push({t:L('فيتامين K يُعطى مرة واحدة عند الولادة (1 ملغ عضلياً). تأكد أنه أُعطي.','Vitamin K is given once at birth (1 mg IM). Make sure it was given.'),r:[56],i:1});
  // vitamin D: 400 IU for breastfed and partially breastfed infants (AAP 2008); 600 IU from 12 months (NIH RDA)
  if(m<12)plan.push({h:L('فيتامين D','Vitamin D'),d:bf?'400 IU'+day+L(' من الأيام الأولى',' from the first days'):L('400 IU يومياً إذا شرب أقل من لتر حليب صناعي مدعّم يومياً','400 IU daily if drinking less than 1 liter of fortified formula a day')});
  else plan.push({h:L('فيتامين D','Vitamin D'),d:'600 IU'+day+L(' (الاحتياج اليومي)',' (daily need)')});
  // iron (AAP 2026): exclusively breastfed term infants 1 mg/kg/day by 4 months; preterm 2–3 mg/kg/day from 2 weeks
  if(pre){const d=w?L(`${fmt(Math.round(w*2*10)/10)} – ${fmt(Math.round(w*3*10)/10)} ملغ يومياً`,`${fmt(Math.round(w*2*10)/10)}–${fmt(Math.round(w*3*10)/10)} mg daily`):L('2 – 3 ملغ/كغم يومياً','2–3 mg/kg daily');
    plan.push({h:L('الحديد (خديج)','Iron (preterm)'),d:d+L(' من عمر أسبوعين مع التغذية الكاملة',' from 2 weeks of age on full feeds')})}
  else if(feed==='bf'&&m<12){if(m>=4){const d=w?L(`${fmt(Math.round(w*10)/10)} ملغ يومياً`,`${fmt(Math.round(w*10)/10)} mg daily`):L('1 ملغ/كغم يومياً','1 mg/kg daily');
      plan.push({h:L('الحديد','Iron'),d:d+L(' من عمر 4 أشهر حتى يأكل أطعمة غنية بالحديد',' from 4 months until eating iron-rich foods')})}
    else plan.push({h:L('الحديد','Iron'),d:L('يبدأ عند عمر 4 أشهر: 1 ملغ/كغم يومياً','Starts at 4 months: 1 mg/kg daily')});}
  else if(feed==='mix'&&m<12)plan.push({h:L('الحديد','Iron'),d:L('يحدده طبيب الأطفال حسب نسبة الحليب الصناعي المدعّم','The pediatrician decides, depending on the share of iron-fortified formula')});
  else if(m<12)plan.push({h:L('الحديد','Iron'),d:L('الحليب الصناعي المدعّم بالحديد يكفي، دون مكمل','Iron-fortified formula is enough; no supplement')});
  else plan.push({h:L('الحديد','Iron'),d:L('7 ملغ يومياً من الغذاء (الاحتياج)','7 mg daily from food (daily need)')});
  if(!w&&(pre||feed==='bf'))notes.push({t:L('أدخل الوزن لحساب جرعة الحديد بالملغ.','Enter the weight to calculate the iron dose in mg.'),i:1});
  if(feed==='bf'&&!pre&&m>=4&&m<12)notes.push({t:L('حسب AAP 2026 يمكن للأهل الانتظار حتى 6 أشهر وبدء أطعمة تحتوي الحديد بدلاً من المكمل.','Per AAP 2026, parents may instead wait until 6 months and start iron-containing foods.'),r:[14]});
  notes.push({t:L('فحص فقر الدم: بين 9 و12 شهراً للرضاعة الطبيعية، وبين 15 و18 شهراً للحليب الصناعي (AAP 2026).','Anemia screening: at 9–12 months if breastfed, and at 15–18 months if formula-fed (AAP 2026).'),r:[14],i:1});
  notes.push({t:L('لا يُعطى الرضيع حليب البقر قبل 12 شهراً، ولا أي مكمل آخر دون طبيب الأطفال.','No cow’s milk before 12 months, and no other supplement without the pediatrician.'),r:[14]});
  const fe=pre||(feed==='bf'&&m>=4&&m<12),DI=m<12?'400':'600';
  const r={badge:L('المكملات الوقائية للرضيع','Infant preventive supplements'),tone:'info',title:bf||m>=12?L(`فيتامين D ${DI} IU يومياً`+(fe?' + حديد':''),`Vitamin D ${DI} IU daily`+(fe?' + iron':'')):L('فيتامين D حسب كمية الحليب الصناعي','Vitamin D depending on formula intake'),
    sub:pre?L('خديج: الحديد من عمر أسبوعين','Preterm: iron from 2 weeks of age'):feed==='bf'?L('رضاعة طبيعية كاملة','Exclusively breastfed'):feed==='mix'?L('رضاعة مختلطة','Mixed feeding'):L('حليب صناعي','Formula-fed'),refs:[55,14,56],plan,
    pt:L(`قطرات فيتامين D ${DI} وحدة يومياً`+(fe?'، وقطرات حديد يومياً بالجرعة التي يحددها طبيب الأطفال حسب الوزن.':'.'),`Vitamin D drops, ${DI} units a day`+(fe?', and iron drops daily at the dose the pediatrician sets by weight.':'.'))};
  if(fe&&w)r.ml={wt:w,mgkg:pre?2:1,q:1};
  r.cal={title:L(`قطرات فيتامين D ${DI} IU`,`Vitamin D drops ${DI} IU`)+(fe?L(' + الحديد',' + iron'):''),freq:'DAILY'};
  r.kv=kv;r.notes=notes;r.tool='drops';render(r);$('iu').value=m<12?400:600;conv();
}

/* ===================== Vitamin A for children 6–59 months (WHO) ===================== */
function fVA(){
  const x=req(['mon']);if(!x)return;
  const m=x.mon,g=$('vag').value,dose=m<6?50000:m<12?100000:200000,D=fmt(dose)+' IU',mcg=fmt(dose*0.3)+' mcg RAE';
  const kv=[[L('الجرعة حسب العمر','Dose for this age'),D+' = '+mcg],[L('الحد الأعلى اليومي (فيتامين A الجاهز)','Daily upper limit (preformed vitamin A)'),L('600 mcg (2,000 IU) حتى 3 سنوات','600 mcg (2,000 IU) up to 3 years')]];
  const notes=[{t:L('هذه جرعات كبيرة تُعطى بالفم على فترات متباعدة بإشراف صحي، وليست جرعة يومية. تجاوزها يسبب تسمماً.','These are large oral doses given at long intervals under health-worker supervision, not a daily dose. Exceeding them causes toxicity.'),r:[53,30],u:1}];let r;
  if(g==='prev'){
    if(m<6)r={badge:L('أقل من 6 أشهر','Under 6 months'),tone:'info',title:L('لا يوصى بالجرعة الوقائية','Preventive dosing is not recommended'),sub:L('برنامج WHO الوقائي يبدأ من عمر 6 أشهر','The WHO preventive program starts at 6 months'),refs:[53],pt:L('لا يحتاج الطفل جرعة فيتامين A وقائية قبل 6 أشهر.','The child does not need a preventive vitamin A dose before 6 months.')};
    else r={badge:L('الوقاية (WHO)','Prevention (WHO)'),tone:'info',title:m<12?L('100,000 IU بالفم مرة واحدة','100,000 IU by mouth, once'):L('200,000 IU بالفم كل 4 – 6 أشهر','200,000 IU by mouth every 4–6 months'),sub:L('فقط في المناطق التي يشكّل فيها نقص فيتامين A مشكلة صحية عامة','Only where vitamin A deficiency is a public health problem'),refs:[53],
      pt:m<12?L('جرعة فيتامين A واحدة بالفم (100,000 وحدة) يعطيها المركز الصحي.','One oral vitamin A dose (100,000 units) given by the health center.'):L('جرعة فيتامين A بالفم (200,000 وحدة) كل 4 إلى 6 أشهر في المركز الصحي.','An oral vitamin A dose (200,000 units) every 4–6 months at the health center.')};
    notes.push({t:L('لا تُعطى للأطفال الأصحاء جيدي التغذية في المناطق التي يندر فيها النقص؛ يكفيهم الغذاء.','Not for well-nourished children where deficiency is rare; food is enough.'),r:[53,30],i:1});
  }else{
    const xer=g==='xer',days=xer?L('اليوم 1 واليوم 2 واليوم 14','Day 1, day 2 and day 14'):L('اليوم 1 واليوم 2','Day 1 and day 2');
    r={badge:xer?L('علاج جفاف الملتحمة والقرنية (Xerophthalmia)','Treating xerophthalmia'):L('الحصبة','Measles'),tone:'bad',title:L(`${D} بالفم: ${days}`,`${D} by mouth: ${days}`),sub:xer?L('ثلاث جرعات حسب WHO، مع تحويل لطبيب العيون','Three doses per WHO, with referral to an eye doctor'):L('جرعتان في يومين متتاليين حسب WHO لتقليل مضاعفات الحصبة','Two doses on consecutive days per WHO, to reduce measles complications'),refs:[54],
      plan:[{h:L('اليوم 1','Day 1'),d:D},{h:L('اليوم 2','Day 2'),d:D},...(xer?[{h:L('اليوم 14','Day 14'),d:D}]:[{h:L('بعد 2 – 4 أسابيع','After 2–4 weeks'),d:L('جرعة ثالثة إذا ظهرت علامات نقص فيتامين A في العين','A third dose if eye signs of vitamin A deficiency appear')}])],
      pt:L(`جرعة فيتامين A بالفم (${D}) في اليوم الأول والثاني`+(xer?' واليوم 14':'')+'، يعطيها الطبيب أو المركز الصحي.',`An oral vitamin A dose (${D}) on day 1 and day 2`+(xer?' and day 14':'')+', given by the doctor or health center.')};
    if(xer)notes.push({t:L('جفاف الملتحمة والقرنية بسبب نقص فيتامين A حالة طارئة قد تسبب العمى: لا يؤخَّر العلاج.','Xerophthalmia from vitamin A deficiency is an emergency that can cause blindness: do not delay treatment.'),r:[54],u:1});
  }
  r.units=['a',dose];
  if(m>59)notes.unshift({t:L('هذه الجرعات لعمر 6 – 59 شهراً. للأكبر يحدد الطبيب الجرعة.','These doses are for 6–59 months. For older children the doctor decides.'),r:[53],u:1});
  r.kv=kv;r.notes=notes;render(r);
}

/* ===================== Pregnancy and breastfeeding: daily supplements ===================== */
function fPreg(){
  const x=req(['age'],['hb']);if(!x)return;
  const age=x.age,hb=x.hb,st=$('tri').value,ntd=$('ntd').checked,lowca=$('lowca').checked,veg=$('veg').checked;
  const preg=st==='t1'||st==='t2'||st==='t3',lac=st==='lac',tn=teen(age)||age<14,tri=preg?+st[1]:null,day=L(' / يوم',' / day');
  const plan=[],notes=[],kv=[];
  // folic acid (WHO ANC 2016, NIH, StatPearls): 400 mcg from before conception; 4–5 mg with a previous neural tube defect
  if(!lac)plan.push({h:L('حمض الفوليك','Folic acid'),d:ntd?L('4 – 5 ملغ يومياً بوصفة طبية','4–5 mg daily on prescription'):'400 mcg'+day+(st==='plan'||st==='t1'?L(' (قبل الحمل بشهر على الأقل وحتى الأسبوع 12)',' (from at least a month before conception to week 12)'):'')});
  // iron: WHO ANC 30–60 mg elemental daily in pregnancy; 120 mg if anemic
  const hc=preg?hbCut(age,'p',tri):null,anem=hb!=null&&hc!=null&&hb<hc;
  if(preg)plan.push({h:L('الحديد','Iron'),d:anem?L('120 ملغ حديد عنصري يومياً حتى يعود الهيموغلوبين طبيعياً','120 mg elemental iron daily until hemoglobin is normal'):L('30 – 60 ملغ حديد عنصري يومياً','30–60 mg elemental iron daily')});
  else plan.push({h:L('الحديد','Iron'),d:(lac?(tn?'10':'9'):(tn?'15':'18'))+L(' ملغ يومياً من الغذاء (الاحتياج)',' mg daily from food (daily need)')});
  // iodine: 150 mcg potassium iodide (American Thyroid Association, in NIH)
  plan.push({h:L('اليود','Iodine'),d:L('150 mcg يومياً كمكمل (يوديد البوتاسيوم)','150 mcg daily as a supplement (potassium iodide)')});
  plan.push({h:L('فيتامين D','Vitamin D'),d:'600 IU'+day});
  plan.push({h:L('الكالسيوم','Calcium'),d:preg&&lowca?L('1,500 – 2,000 ملغ يومياً مقسّمة (غذاء قليل الكالسيوم)','1,500–2,000 mg daily, divided (low-calcium diet)'):(tn?'1,300':'1,000')+L(' ملغ يومياً من الغذاء والمكمل',' mg daily from food and supplements')});
  plan.push({h:L('الكولين','Choline'),d:(lac?'550':preg?'450':'425')+L(' ملغ يومياً (بيض، لحوم، أسماك)',' mg daily (eggs, meat, fish)')});
  plan.push({h:L('أوميغا-3 (DHA)','Omega-3 (DHA)'),d:L('225 – 340 غ سمك قليل الزئبق أسبوعياً','225–340 g of low-mercury fish a week')});
  if(veg)plan.push({h:'B12',d:(lac?'2.8':preg?'2.6':'2.4')+L(' mcg يومياً كمكمل (نظام نباتي)',' mcg daily as a supplement (vegan diet)')});
  if(hb!=null){kv.push([L('الهيموغلوبين','Hemoglobin'),fmt(hb)+' g/dL']);if(hc!=null)kv.push([L('فقر الدم تحت (WHO)','Anemia below (WHO)'),fmt(hc)+' g/dL'])}
  kv.push([L('الحد الأعلى لفيتامين A الجاهز','Upper limit for preformed vitamin A'),tn?'2,800 mcg (9,333 IU)':'3,000 mcg (10,000 IU)']);
  if(anem)notes.push({t:L(`الهيموغلوبين أقل من ${fmt(hc)} g/dL: فقر دم في الحمل حسب WHO. افحص Ferritin، وتحدد طبيبة النسائية والتوليد العلاج.`,`Hemoglobin below ${fmt(hc)} g/dL: anemia in pregnancy per WHO. Check ferritin; the obstetrician decides treatment.`),r:[51,57],u:1});
  if(ntd)notes.push({t:L('جرعة 4 – 5 ملغ أعلى من الحد الأعلى العام (1,000 mcg) وتؤخذ بإشراف طبي فقط.','4–5 mg exceeds the general upper limit (1,000 mcg) and is for medical supervision only.'),r:[67,11],u:1});
  notes.push({t:L('تجنبي مكملات فيتامين A (Retinol) بجرعات عالية في الحمل لأنها قد تسبب تشوهات؛ لا تتجاوزي الحد الأعلى.','Avoid high-dose vitamin A (retinol) supplements in pregnancy because they can cause birth defects; stay under the upper limit.'),r:[30],u:preg?1:0});
  notes.push({t:L('افصلي الحديد عن الكالسيوم بساعتين على الأقل لأن الكالسيوم يقلل امتصاص الحديد.','Take iron and calcium at least 2 hours apart, because calcium lowers iron absorption.'),r:[18,15]});
  if(preg&&lowca)notes.push({t:L('توصي WHO بالكالسيوم 1.5 – 2 غ يومياً للحوامل ذوات المدخول المنخفض لتقليل خطر مقدمات الارتعاج (تسمم الحمل).','WHO recommends 1.5–2 g calcium daily for pregnant women with low intake to reduce the risk of preeclampsia.'),r:[57,18],i:1});
  notes.push({t:L('لا يُفحص فيتامين D روتينياً في الحمل؛ توصي Endocrine Society 2024 بالمكمل وقائياً للحوامل.','Vitamin D is not tested routinely in pregnancy; Endocrine Society 2024 suggests a preventive supplement in pregnancy.'),r:[3,4],i:1});
  if(CKD())notes.unshift({t:L('مع القصور الكلوي المتقدم تحدد طبيبة النسائية والتوليد وطبيب الكلى المكملات وجرعاتها، خاصة الكالسيوم وفيتامين D والحديد.','With advanced kidney disease the obstetrician and the nephrologist set the supplements and their doses, especially calcium, vitamin D and iron.'),r:[61,62],u:1});
  if(age<12)notes.unshift({t:L('العمر المدخل لا يناسب الحمل؛ تأكدي من العمر.','The age entered does not fit pregnancy; check the age.'),u:1});
  const badge=st==='plan'?L('التخطيط للحمل','Planning pregnancy'):lac?L('الرضاعة الطبيعية','Breastfeeding'):L(`الحمل: الثلث ${['الأول','الثاني','الثالث'][tri-1]}`,`Pregnancy: trimester ${tri}`);
  const r={badge,tone:anem?'warn':'info',title:lac?L('يود 150 mcg يومياً + غذاء متوازن','Iodine 150 mcg daily + a balanced diet'):preg?L('حمض الفوليك + الحديد + اليود يومياً','Folic acid + iron + iodine daily'):L('حمض الفوليك + اليود يومياً','Folic acid + iodine daily'),
    sub:L('مع فيتامين D والكالسيوم والكولين والأوميغا-3 من الغذاء أو المكملات','With vitamin D, calcium, choline and omega-3 from food or supplements'),refs:[57,65,11,15,37,4,18,44,42],plan,
    pt:lac?L('حبة يود 150 ميكروغرام يومياً، مع غذاء متوازن وسمك قليل الزئبق مرتين أسبوعياً.','A 150-microgram iodine tablet a day, with a balanced diet and low-mercury fish twice a week.'):
      preg?L('يومياً: حمض الفوليك، وحبة حديد، ويود 150 ميكروغرام، حسب ما تحدده طبيبة النسائية والتوليد. افصلي الحديد عن الكالسيوم بساعتين.','Every day: folic acid, an iron tablet and 150 micrograms of iodine, as your obstetrician advises. Take iron and calcium 2 hours apart.'):
      L('ابدئي حمض الفوليك 400 ميكروغرام ويود 150 ميكروغرام يومياً قبل الحمل بشهر على الأقل.','Start folic acid 400 micrograms and iodine 150 micrograms a day at least a month before pregnancy.')};
  if(preg){r.tool='pills';PILL={k:'fe',dose:anem?120:60}}
  r.cal={title:lac?L('يود 150 mcg','Iodine 150 mcg'):L('مكملات الحمل: حمض الفوليك + الحديد + اليود','Pregnancy supplements: folic acid + iron + iodine'),freq:'DAILY'};
  r.sch=preg||lac?['fe','ca',...(preg&&lowca?['ca2']:[])]:['ca'];
  r.ul=[...(st!=='lac'&&!ntd?[['fol',400]]:[]),['io',150],['d',600]];
  r.kv=kv;r.notes=notes;render(r);
}

/* ===================== After weight-loss (bariatric) surgery: daily preventive supplements (ASMBS 2016, Table 3) ===================== */
function fBar(){
  const x=req(['age']);if(!x)return;
  const age=x.age,sx=$('sex').value,sp=$('bsp').value,anh=$('banem').checked,day=L(' / يوم',' / day');
  const ds=sp==='bpd',band=sp==='lagb',fem=sx!=='m',men=fem&&age>=12&&age<=50,childb=fem&&age>=14&&age<=50;
  const lowFe=!men&&!anh&&band; // ASMBS: low risk = males / no anemia history; RYGB, SG and BPD/DS always take 45–60 mg
  const SPN={sg:L('تكميم المعدة (SG)','Sleeve gastrectomy (SG)'),rygb:L('تحويل المسار (RYGB)','Roux-en-Y gastric bypass (RYGB)'),lagb:L('ربط المعدة (LAGB)','Adjustable gastric band (LAGB)'),bpd:L('تحويل الاثني عشر (BPD/DS)','Duodenal switch (BPD/DS)')}[sp];
  const plan=[
    {h:L('متعدد الفيتامينات والمعادن','Multivitamin with minerals'),d:L('يومياً، ومنه الزنك والنحاس','Daily; it also provides zinc and copper')},
    {h:L('الثيامين (B1)','Thiamine (B1)'),d:L('12 ملغ يومياً على الأقل، والأفضل 50 ملغ مرة أو مرتين يومياً','At least 12 mg daily, preferably 50 mg once or twice daily')},
    {h:'B12',d:L('350 – 500 mcg يومياً بالفم أو تحت اللسان، أو 1,000 mcg عضلياً كل شهر','350–500 mcg daily by mouth or under the tongue, or 1,000 mcg IM monthly')},
    {h:L('حمض الفوليك','Folic acid'),d:childb?L('800 – 1,000 mcg يومياً (امرأة في سن الإنجاب)','800–1,000 mcg daily (woman of childbearing age)'):'400 – 800 mcg'+day},
    {h:L('الحديد','Iron'),d:lowFe?L('18 ملغ يومياً على الأقل من متعدد الفيتامينات','At least 18 mg daily from the multivitamin'):L('45 – 60 ملغ حديد عنصري يومياً (مجموع كل المكملات)، مقسّمة','45–60 mg elemental iron daily (total from all supplements), divided')},
    {h:L('الكالسيوم','Calcium'),d:(ds?'1,800 – 2,400':'1,200 – 1,500')+L(' ملغ يومياً من كل المصادر، مقسّمة على جرعات',' mg daily from all sources, in divided doses')},
    {h:L('فيتامين D3','Vitamin D3'),d:L('3,000 IU يومياً حتى يتجاوز 25(OH)D مستوى 30 ng/mL','3,000 IU daily until 25(OH)D is above 30 ng/mL')},
    {h:L('فيتامين A','Vitamin A'),d:(band?'5,000':ds?'10,000':'5,000 – 10,000')+' IU'+day},
    {h:L('فيتامين K','Vitamin K'),d:(ds?'300':'90 – 120')+' mcg'+day},
    {h:L('فيتامين E','Vitamin E'),d:'15 '+L('ملغ','mg')+day},
    {h:L('الزنك','Zinc'),d:(ds?'16 – 22':sp==='rygb'?'8 – 22':'8 – 11')+L(' ملغ',' mg')+day},
    {h:L('النحاس','Copper'),d:(ds||sp==='rygb'?'2':'1')+L(' ملغ',' mg')+day+L('؛ 1 ملغ لكل 8 – 15 ملغ زنك','; 1 mg for every 8–15 mg of zinc')}];
  const notes=[
    {t:L('خذ الحديد في جرعات منفصلة عن الكالسيوم وأدوية الحموضة والشاي والقهوة والأطعمة الغنية بالفايتات.','Take iron separately from calcium, acid-reducing medicines, tea, coffee and phytate-rich foods.'),r:[69]},
    {t:L('Calcium citrate مع الطعام أو بدونه، وCalcium carbonate مع الطعام فقط؛ في جرعات مقسّمة.','Calcium citrate with or without food; calcium carbonate with food only; in divided doses.'),r:[69]},
    {t:L('التحاليل: كل 3 – 6 أشهر في السنة الأولى، ثم سنوياً.','Blood tests: every 3–6 months in the first year, then yearly.'),r:[69],i:1}];
  if(sx==='p')notes.unshift({t:L('في الحمل بعد عمليات السمنة يحتاج فيتامين A وK متابعة خاصة؛ لا تتجاوزي جرعة فيتامين A دون طبيب.','In pregnancy after weight-loss surgery vitamins A and K need special care; do not exceed the vitamin A dose without a doctor.'),r:[69],u:1});
  if(age<18)notes.unshift({t:L('هذه توصيات البالغين. للمراهقين يحدد فريق جراحة السمنة الجرعات.','These are adult recommendations. For adolescents the bariatric team sets the doses.'),r:[69],u:1});
  if(CKD())notes.unshift({t:L('مع القصور الكلوي المتقدم يحدد طبيب الكلى الكالسيوم وفيتامين D والمعادن.','With advanced kidney disease the nephrologist sets calcium, vitamin D and minerals.'),r:[61],u:1});
  const r={badge:SPN,tone:'info',title:L('المكملات اليومية الوقائية بعد عملية السمنة','Daily preventive supplements after weight-loss surgery'),sub:L('حسب نوع العملية، مدى الحياة غالباً','By type of surgery, usually lifelong'),refs:[69],plan,
    pt:L('بعد عملية السمنة تحتاج يومياً: حبة متعدد فيتامينات، وB12، وكالسيوم مقسّماً على اليوم، وفيتامين D، وحديد في وقت منفصل عن الكالسيوم. الجرعات في الخطة أدناه، ويتابعها طبيبك بالتحاليل.','After weight-loss surgery you need every day: a multivitamin, B12, calcium split through the day, vitamin D, and iron at a different time from calcium. The doses are in the plan below; your doctor follows them with blood tests.')};
  r.kv=[[L('العملية','Surgery'),SPN],[L('الكالسيوم من كل المصادر','Calcium from all sources'),(ds?'1,800 – 2,400':'1,200 – 1,500')+L(' ملغ / يوم',' mg / day')]];
  r.notes=notes;r.sch=['fe','ca','ca2'];r.cal={title:L('مكملات ما بعد عملية السمنة','Supplements after weight-loss surgery'),freq:'DAILY'};
  render(r);
}

/* ===================== Thiamine (B1): deficiency and alcohol (NHS SPS 2024; BNF doses via NHS Highland formulary) ===================== */
function fThi(){
  const x=req(['age']);if(!x)return;
  const age=x.age,g=$('thg').value,MG=L(' ملغ',' mg');
  const notes=[];let r;
  if(g==='mild')r={badge:L('نقص خفيف','Mild deficiency'),tone:'info',title:L('25 ملغ ثيامين فموياً يومياً','Thiamine 25 mg by mouth daily'),sub:L('مع علاج السبب وتحسين الغذاء','With treatment of the cause and a better diet'),refs:[71],
    pt:L('حبة ثيامين (فيتامين B1) 25 ملغ يومياً.','One thiamine (vitamin B1) 25 mg tablet a day.')};
  else if(g==='sev')r={badge:L('نقص شديد','Severe deficiency'),tone:'warn',title:L('200 – 300 ملغ فموياً يومياً، مقسّمة','200–300 mg by mouth daily, divided'),sub:L('بإشراف الطبيب','Under medical supervision'),refs:[71],
    pt:L('ثيامين 200 إلى 300 ملغ يومياً مقسّمة على جرعات، حسب الطبيب.','Thiamine 200–300 mg a day in divided doses, as your doctor advises.')};
  else if(g==='alc'){r={badge:L('الاعتماد على الكحول','Alcohol dependence'),tone:'warn',title:L('200 – 300 ملغ ثيامين فموياً يومياً، مقسّمة','Thiamine 200–300 mg by mouth daily, divided'),sub:L('قبل الانسحاب المخطط وأثناء الانسحاب الحاد، وحتى 12 شهراً بعده','Before planned withdrawal, during acute withdrawal, and up to 12 months after'),refs:[71,70],
    pt:L('ثيامين (فيتامين B1) 200 إلى 300 ملغ يومياً مقسّمة على جرعات، للمدة التي يحددها الطبيب.','Thiamine (vitamin B1) 200–300 mg a day in divided doses, for as long as your doctor says.'),
    plan:[{h:L('قبل الانسحاب وأثناءه','Before and during withdrawal'),d:L('200 – 300 ملغ يومياً مقسّمة','200–300 mg daily, divided')},{h:L('بعده','Afterwards'),d:L('حتى 12 شهراً، وأحياناً لمدة أطول','Up to 12 months, sometimes longer')}]};
    notes.push({t:L('امتصاص الثيامين الفموي ضعيف مع الكحول، لذلك تُقسّم الجرعة على اليوم. إذا وُجدت علامات خطورة عالية فالحقن أولاً.','Oral thiamine is poorly absorbed with alcohol, so the dose is divided through the day. With high-risk signs, injections come first.'),r:[70,71],i:1})}
  else if(g==='risk'){r={badge:L('خطورة عالية لاعتلال فيرنيكه','High risk of Wernicke encephalopathy'),tone:'bad',title:L('ثيامين 200 – 300 ملغ بالحقن مرة يومياً','Thiamine 200–300 mg by injection once daily'),sub:L('في المجتمع: عضلياً لمدة 3 أيام على الأقل. في المستشفى: عضلياً أو وريدياً لمدة 3 – 5 أيام مع مراجعة يومية. ثم الفموي','Community: IM for at least 3 days. Hospital: IM or IV for 3–5 days with daily review. Then oral'),refs:[70],
    pt:L('تحتاج حقن فيتامين B1 (ثيامين) لعدة أيام لحماية الدماغ، ثم حبوب. راجع الطبيب اليوم.','You need vitamin B1 (thiamine) injections for a few days to protect the brain, then tablets. See a doctor today.'),
    plan:[{h:L('الحقن: 3 – 5 أيام','Injections: 3–5 days'),d:L('200 – 300 ملغ مرة يومياً','200–300 mg once daily')},{h:L('بعدها','Then'),d:L('200 – 300 ملغ فموياً يومياً مقسّمة','200–300 mg by mouth daily, divided')}]};
    notes.push({t:L('علامات الخطورة العالية: نقص وزن كبير، غذاء سيئ، نحافة شديدة أو سوء تغذية، ضعف الذاكرة، اعتلال الأعصاب الطرفية، إصابة سابقة باعتلال فيرنيكه.','High-risk signs: marked weight loss, poor diet, very low BMI or other malnutrition, memory problems, peripheral neuropathy, previous Wernicke encephalopathy.'),r:[70]})}
  else{r={badge:L('اشتباه اعتلال فيرنيكه','Suspected Wernicke encephalopathy'),tone:'bad',title:L('طوارئ: ثيامين وريدي 300 – 500 ملغ 3 مرات يومياً','Emergency: IV thiamine 300–500 mg three times daily'),sub:L('لمدة 3 – 5 أيام مع مراجعة يومية؛ إن استمرت الأعراض: 300 – 500 ملغ مرة يومياً 3 – 5 أيام أخرى ما دام التحسن مستمراً','For 3–5 days with daily review; if symptoms persist: 300–500 mg once daily for a further 3–5 days while improvement continues'),refs:[70],
    pt:L('اذهب إلى الطوارئ الآن. هذه الأعراض قد تكون نقصاً شديداً في فيتامين B1 يحتاج حقناً وريدية فورية.','Go to the emergency department now. These symptoms may be severe vitamin B1 deficiency that needs IV treatment straight away.'),
    plan:[{h:L('أول 3 – 5 أيام','First 3–5 days'),d:L('300 – 500 ملغ وريدياً 3 مرات يومياً','300–500 mg IV three times daily')},{h:L('إن استمرت الأعراض','If symptoms persist'),d:L('300 – 500 ملغ وريدياً مرة يومياً 3 – 5 أيام','300–500 mg IV once daily for 3–5 days')}]};
    notes.unshift({t:L('أي من: اضطراب حركة العين، عدم ثبات المشي، التشوش الذهني، يكفي للبدء بالعلاج فوراً؛ مع البحث عن أسباب أخرى للتشوش.','Any of impaired eye movements, unsteady walking or confusion is enough to start treatment straight away; also look for other causes of confusion.'),r:[70],u:1})}
  if(age<18)notes.unshift({t:L('هذه جرعات البالغين. للأطفال يحدد الطبيب الجرعة.','These are adult doses. A doctor sets the dose for children.'),r:[71],u:1});
  r.kv=[[RDAL(age),age<1?L('0.2 – 0.3 ملغ','0.2–0.3 mg'):age<=3?'0.5'+MG:age<=8?'0.6'+MG:age<=13?'0.9'+MG:$('sex').value==='p'||$('sex').value==='l'?'1.4'+MG:$('sex').value==='m'?'1.2'+MG:age<=18?'1.0'+MG:'1.1'+MG],[L('الحد الأعلى','Upper limit'),L('غير محدد','Not established')]];
  r.notes=notes;render(r);
}

